import { STEPPER_TOKENS as T } from './tokens'

const { dotSize, colors, checkStrokeWidth, currentRingRadius, currentRingStroke } = T

export function StepDoneIcon() {
  const cx = dotSize / 2
  const cy = dotSize / 2
  const r = dotSize / 2

  return (
    <svg
      width={dotSize}
      height={dotSize}
      viewBox={`0 0 ${dotSize} ${dotSize}`}
      fill="none"
      aria-hidden
    >
      <circle cx={cx} cy={cy} r={r} fill={colors.done} />
      <path
        d="M10 17.5 L14.5 22 L24 12"
        stroke={colors.white}
        strokeWidth={checkStrokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

export function StepCurrentIcon() {
  const cx = dotSize / 2
  const cy = dotSize / 2
  const r = dotSize / 2

  return (
    <svg
      width={dotSize}
      height={dotSize}
      viewBox={`0 0 ${dotSize} ${dotSize}`}
      fill="none"
      aria-hidden
    >
      <circle cx={cx} cy={cy} r={r} fill={colors.current} />
      <circle
        cx={cx}
        cy={cy}
        r={currentRingRadius}
        fill="none"
        stroke={colors.white}
        strokeWidth={currentRingStroke}
      />
    </svg>
  )
}

export function StepUpcomingIcon({ stepNumber }) {
  const cx = dotSize / 2
  const cy = dotSize / 2
  const r = dotSize / 2 - T.upcomingBorderWidth / 2

  return (
    <svg
      width={dotSize}
      height={dotSize}
      viewBox={`0 0 ${dotSize} ${dotSize}`}
      fill="none"
      aria-hidden
    >
      <circle
        cx={cx}
        cy={cy}
        r={r}
        fill={colors.white}
        stroke={colors.upcomingBorder}
        strokeWidth={T.upcomingBorderWidth}
      />
      <text
        x={cx}
        y={cy}
        textAnchor="middle"
        dominantBaseline="central"
        fill={colors.upcomingText}
        fontFamily="Muli, Mulish, sans-serif"
        fontSize={T.upcomingNumber.fontSize}
        fontWeight={T.upcomingNumber.fontWeight}
      >
        {stepNumber}
      </text>
    </svg>
  )
}
