import { useCallback, useEffect, useMemo } from 'react'
import { useHistory, useLocation } from 'react-router-dom'
import { getPublicClaimStatus } from '../mock'
import {
  CLAIM_NO_QUERY,
  hasClaimStatusGate,
  setLoginStatusTab,
} from '../session'

export function useClaimStatusPage() {
  const history = useHistory()
  const location = useLocation()
  const claimNo = new URLSearchParams(location.search).get(CLAIM_NO_QUERY)
  const data = useMemo(
    () => (claimNo ? getPublicClaimStatus(claimNo) : null),
    [claimNo]
  )
  const shouldRedirect = !hasClaimStatusGate(claimNo)

  const handleViewClaimDetail = useCallback(() => {
    history.push('/login')
  }, [history])

  useEffect(() => {
    if (shouldRedirect) {
      setLoginStatusTab()
    }
  }, [shouldRedirect])

  return {
    claimNo,
    data,
    shouldRedirect,
    handleViewClaimDetail,
  }
}
