import IntlMessages from '../../../../components/utility/intlMessages'
import { Card, CardTitle } from '../ClaimStatusCard.styles'
import {
  Timeline,
  TimelineBody,
  TimelineDot,
  TimelineMessage,
  TimelineRail,
  TimelineRow,
  TimelineStem,
  TimelineTime,
} from './styles'

function ClaimStatusTimeline({ statusHistory }) {
  return (
    <Card data-testid="org-claim-status-timeline">
      <CardTitle>
        <IntlMessages id="Klaim Status" />
      </CardTitle>
      {statusHistory && statusHistory.length > 0 ? (
        <Timeline data-testid="org-claim-status-timeline-list">
          {statusHistory.map((item, index) => {
            const last = index === statusHistory.length - 1
            const current = item.is_current

            return (
              <TimelineRow key={`${item.timestamp}-${index}`}>
                <TimelineRail>
                  <TimelineDot current={current} />
                  {!last ? <TimelineStem current={current} /> : null}
                </TimelineRail>
                <TimelineBody last={last}>
                  <TimelineMessage current={current}>
                    <IntlMessages id={item.message} />
                  </TimelineMessage>
                  <TimelineTime current={current}>{item.timestamp}</TimelineTime>
                </TimelineBody>
              </TimelineRow>
            )
          })}
        </Timeline>
      ) : null}
    </Card>
  )
}

export default ClaimStatusTimeline
