import IntlMessages from '../../../../components/utility/intlMessages'
import { StepCurrentIcon, StepDoneIcon, StepUpcomingIcon } from './icons'
import { StepIconWrap, StepItem, StepLabel, StepLine, StepNode, Stepper } from './styles'

const STEPS = [
  { id: 'mulai', label: 'Mulai' },
  { id: 'form', label: 'Form' },
  { id: 'verifikasi', label: 'Verifikasi' },
  { id: 'konfirmasi', label: 'Konfirmasi' },
  { id: 'selesai', label: 'Selesai' },
]

function getLineKind(index, currentIndex) {
  if (index < currentIndex - 1) return 'done'
  if (index === currentIndex - 1) return 'current'
  return 'upcoming'
}

function ClaimLifecycleStepper({ currentStep }) {
  const currentIndex = STEPS.findIndex((s) => s.id === currentStep)

  return (
    <Stepper data-testid="org-claim-status-stepper">
      {STEPS.map((step, index) => {
        const done = index < currentIndex
        const current = index === currentIndex
        const kind = done ? 'done' : current ? 'current' : 'upcoming'
        const last = index === STEPS.length - 1
        const lineKind = last ? null : getLineKind(index, currentIndex)

        return (
          <StepItem key={step.id} last={last}>
            <StepNode>
              <StepIconWrap>
                {done ? (
                  <StepDoneIcon />
                ) : current ? (
                  <StepCurrentIcon />
                ) : (
                  <StepUpcomingIcon stepNumber={index + 1} />
                )}
              </StepIconWrap>
              <StepLabel kind={kind}>
                <IntlMessages id={step.label} />
              </StepLabel>
            </StepNode>
            {lineKind ? <StepLine kind={lineKind} /> : null}
          </StepItem>
        )
      })}
    </Stepper>
  )
}

export default ClaimLifecycleStepper
