import { Redirect } from 'react-router-dom'
import IntlMessages from '../../components/utility/intlMessages'
import ClaimLifecycleStepper from './components/ClaimLifecycleStepper'
import ClaimStatusBottom from './components/ClaimStatusBottom'
import ClaimStatusHeader from './components/ClaimStatusHeader'
import ClaimStatusInfoCard from './components/ClaimStatusInfoCard'
import ClaimStatusTimeline from './components/ClaimStatusTimeline'
import { useClaimStatusPage } from './hooks/useClaimStatusPage'
import { Inner, Main, NotFound, Page, StepperBand } from './styles'

function ClaimStatusPage() {
  const { data, shouldRedirect, handleViewClaimDetail } = useClaimStatusPage()

  if (shouldRedirect) {
    return <Redirect to="/login" />
  }

  return (
    <Page data-testid="page-claim-status">
      <Main>
        {data ? (
          <>
            <ClaimStatusHeader
              displayId={data.display_id}
              onViewDetail={handleViewClaimDetail}
            />
            <Inner>
              <StepperBand>
                <ClaimLifecycleStepper currentStep={data.current_step} />
              </StepperBand>
              <ClaimStatusTimeline statusHistory={data.status_history} />
              <ClaimStatusInfoCard info={data.info} />
            </Inner>
          </>
        ) : (
          <Inner>
            <NotFound data-testid="mol-claim-status-not-found">
              <IntlMessages id="Klaim tidak ditemukan" />
            </NotFound>
          </Inner>
        )}
      </Main>
      <ClaimStatusBottom />
    </Page>
  )
}

export default ClaimStatusPage
