// ponytail: any KLM-<digits> returns the Figma fixture until the public status API exists
const KLM_CLAIM_PATTERN = /^KLM-\d+$/

export function getPublicClaimStatus(claimNo) {
  if (!claimNo) return null
  const normalized = claimNo.trim().toUpperCase()
  if (!KLM_CLAIM_PATTERN.test(normalized)) return null
  return { ...MOCK_PUBLIC_CLAIM_STATUS, claim_no: normalized }
}
