export const CLAIM_STATUS_GATE_KEY = 'claimStatusLookup'
export const LOGIN_STATUS_TAB_KEY = 'loginTab'
export const CHECK_STATUS_PATH = '/check-status'
export const CLAIM_NO_QUERY = 'claimNo'

export function checkStatusUrl(claimNo) {
  return `${CHECK_STATUS_PATH}?${CLAIM_NO_QUERY}=${encodeURIComponent(claimNo)}`
}

export function setClaimStatusGate(claimNo) {
  window.sessionStorage.setItem(CLAIM_STATUS_GATE_KEY, claimNo)
}

export function clearClaimStatusGate() {
  window.sessionStorage.removeItem(CLAIM_STATUS_GATE_KEY)
}

export function hasClaimStatusGate(claimNo) {
  if (!claimNo) return false
  return window.sessionStorage.getItem(CLAIM_STATUS_GATE_KEY) === claimNo
}

export function setLoginStatusTab() {
  window.sessionStorage.setItem(LOGIN_STATUS_TAB_KEY, 'status')
}

export function consumeLoginStatusTab() {
  if (window.sessionStorage.getItem(LOGIN_STATUS_TAB_KEY) !== 'status') return false
  window.sessionStorage.removeItem(LOGIN_STATUS_TAB_KEY)
  return true
}
